#[inductive(produce_start)]
fn produce_start_inductive(pre: Self, post: Self) {
    broadcast use group_map_lemmas;

    let tail = pre.producer.get_Idle_0();

    // Get key facts about the transition:
    // 1. post.producer = Producing(tail) (was Idle(tail))
    // 2. post.storage = pre.storage.remove(tail)
    // 3. post.head = pre.head, post.tail = pre.tail
    // 4. post.backing_cells = pre.backing_cells
    // 5. post.consumer = pre.consumer (unchanged)

    // Show: forall|i| 0 <= i < post.len() => post.valid_storage_at_idx(i)
    assert(forall|i: nat| 0 <= i && i < post.len() ==> post.valid_storage_at_idx(i)) by {
        assert forall|i: nat| 0 <= i && i < post.len() ==> post.valid_storage_at_idx(i) by {
            if i == tail {
                // i == tail case
                // is_checked_out: producer is Producing(tail), so tail is checked out
                assert(post.is_checked_out(i));

                // storage: we withdrew tail, so it's not in storage anymore
                assert(!post.storage.dom().contains(i));
            } else {
                // i != tail case
                // is_checked_out unchanged for i != tail (only producer at tail changed)
                assert(post.is_checked_out(i) == pre.is_checked_out(i));

                // Storage domain: only tail was removed, and i != tail, so membership unchanged
                assert(post.storage.dom().contains(i) == pre.storage.dom().contains(i));

                // Storage content unchanged for i != tail
                assert(post.storage.index(i) == pre.storage.index(i));

                if pre.is_checked_out(i) {
                    // Was checked out in pre state, so not in storage
                    assert(!pre.storage.dom().contains(i));
                    assert(!post.storage.dom().contains(i));
                } else {
                    // Was not checked out in pre state, so in storage with correct content
                    assert(pre.storage.dom().contains(i));
                    assert(post.storage.dom().contains(i));

                    // IDs: unchanged because backing_cells unchanged
                    assert(post.storage.index(i).id() == pre.storage.index(i).id());
                    assert(pre.storage.index(i).id() == pre.backing_cells.index(i as int));
                    assert(post.backing_cells.index(i as int) == pre.backing_cells.index(i as int));

                    // Content (init/uninit): unchanged
                    assert(post.storage.index(i).is_init() == pre.storage.index(i).is_init());
                    assert(post.storage.index(i).is_uninit() == pre.storage.index(i).is_uninit());

                    // in_active_range: depends only on head/tail which are unchanged
                    assert(post.in_active_range(i) == pre.in_active_range(i));
                }
            }
        }
    };
}

