    //   post.storage.dom() = pre.storage.dom() - {tail}, but since i != tail,
    //                        membership is unchanged
    //   So valid_storage_at_idx(i) holds because it held in pre state.

    // Use Map axioms
    broadcast use group_map_lemmas;

    // Get the tail value from the pre state
    let tail = pre.producer.get_Idle_0();

    // Show for all i: 0 <= i < post.len() => valid_storage_at_idx(i)
