                post.is_checked_out(i) == pre.is_checked_out(i)
                && (
                    pre.is_checked_out(i) ==>
                        !pre.storage.dom().contains(i)
                )
                && (
                    !pre.is_checked_out(i) ==>
                        post.storage.dom().contains(i)
                        && post.storage.index(i).id() == post.backing_cells.index(i as int)
                        && if post.in_active_range(i) {
                            post.storage.index(i).is_init()
                        } else {
                            post.storage.index(i).is_uninit()
                        }
                )
            }
        }
    };
}

