fn produce_start_inductive(pre: Self, post: Self) {
    broadcast use group_map_lemmas;

    let tail = pre.producer.get_Idle_0();

    // Use the pre-state invariants
    assert(pre.valid_storage_all());
    assert(pre.in_bounds());
    assert(pre.not_overlapping());

    // After produce_start:
    // - storage was updated: post.storage = pre.storage.remove(tail)
    // - producer was updated: post.producer = Producing(tail) (pre.producer = Idle(tail))
    // - other fields unchanged

    // Show: forall|i| 0 <= i < post.len() => post.valid_storage_at_idx(i)
    assert(forall|i: nat| 0 <= i && i < post.len() ==> post.valid_storage_at_idx(i)) by {
        assert forall|i: nat| 0 <= i && i < post.len() ==> post.valid_storage_at_idx(i) &
            // Show valid_storage_at_idx(i) for both cases
            (if i == tail {
                // Case 1: i == tail
                // In post state:
                // - producer is Producing(tail), so is_checked_out(i) is true
                // - storage was updated to remove tail, so storage.dom() doesn't contain i
                post.is_checked_out(i) && !post.storage.dom().contains(i)
            } else {
                // Case 2: i != tail
                // In post state:
                // - is_checked_out(i) is unchanged from pre state
                // - storage.dom() membership is unchanged (remove(tail) doesn't affect i)
                // - storage index is unchanged for i
                let post_ico = post.is_checked_out(i);  // post_ico means post.is_checked_out(i)
                let post_dom = post.storage.dom().contains(i);
                let post_id = post.storage.index(i).id();
                let post_bc = post.backing_cells.index(i as int);
                let post_init = post.storage.index(i).is_init();
                let post_uninit = post.storage.index(i).is_uninit();
                let post_ar = post.in_active_range(i);

                let pre_ico = pre.is_checked_out(i);
                let pre_dom = pre.storage.dom().contains(i);
                let pre_id = pre.storage.index(i).id();
                let pre_bc = pre.backing_cells.index(i as int);
                let pre_ar = pre.in_active_range(i);

                // Key equalities from the transition
                post_ico == pre_ico
                && post_dom == pre_dom
                && post_id == pre_id
                && post_bc == pre_bc
                && post_init == pre.storage.index(i).is_init()
                && post_uninit == pre.storage.index(i).is_uninit()
                && post_ar == pre_ar
            }) by {
            // Case 1: i == tail
            if i == tail {
                // producer changed to Producing(tail)
                assert(post.producer == ProducerState::Producing(tail));
                assert(post.is_checked_out(i));

                // storage was updated by removing tail
                assert(post.storage.dom() == pre.storage.dom().remove(tail));
                assert(!pre.storage.dom().contains(tail) || tail == tail);  // trivial
                assert(!post.storage.dom().contains(i));
            }
            // Case 2: i != tail
            else {
                // is_checked_out unchanged for i != tail (only tail changed)
                assert(post.producer == ProducerState::Producing(tail));
                assert(pre.producer == ProducerState::Idle(tail));
                assert(post.is_checked_out(i) == pre.is_checked_out(i));

                // storage domain: remove(tail) doesn't affect i when i != tail
                assert(post.storage.dom() == pre.storage.dom().remove(tail));
                assert(post.storage.dom().contains(i) == pre.storage.dom().contains(i));

                // storage index: remove different key preserves value
                // Apply axiom_map_remove_different: if i != tail, then remove(tail)[i] == [i]
                // But post.storage = pre.storage.remove(tail), so post.storage.index(i) == pre.storage.index(i)
                assert(post.storage.index(i) == pre.storage.index(i));

                // Use pre-state invariant for the rest
                assert(pre.valid_storage_at_idx(i));

                // in_active_range unchanged (head/tail unchanged)
                assert(post.in_active_range(i) == pre.in_active_range(i));

                // backing_cells unchanged (constant)
                assert(post.backing_cells == pre.backing_cells);
            }
        };
    };
}

