#[inductive(produce_start)]
fn produce_start_inductive(pre: Self, post: Self) {
    broadcast use group_map_lemmas;

    let tail = pre.producer.get_Idle_0();

    // Key facts from the transition:
    assert(post.storage.dom() == pre.storage.dom().remove(tail));
    assert(post.producer == ProducerState::Producing(tail));

    // Show: post.valid_storage_all()
    // i.e., forall|i| 0 <= i < post.len() ==> post.valid_storage_at_idx(i)
    assert(forall|i: nat| 0 <= i && i < post.len() ==> post.valid_storage_at_idx(i)) by {
        // Use the pre-state invariant pre.valid_storage_all()
        assert(pre.valid_storage_all());

        assert forall|i: nat| 0 <= i && i < post.len() ==> post.valid_storage_at_idx(i) by {
            // For i == tail:
            //   post.is_checked_out(i) = true (producer is Producing(tail))
            //   post.storage.dom().contains(i) = false (removed)
            //   So valid_storage_at_idx(i) = true && true = true
            //
            // For i != tail:
            //   post.is_checked_out(i) = pre.is_checked_out(i)
            //   post.storage.dom().contains(i) = pre.storage.dom().contains(i)
            //   post.storage.index(i).id() = pre.storage.index(i).id()
            //   pre.storage.index(i).id() = pre.backing_cells.index(i as int) (by pre invariant)
            //   post.backing_cells.index(i as int) = pre.backing_cells.index(i as int) (unchanged)
            //   So the ID part holds.
            //   The is_init/uninit part follows similarly.

            // Since i is in bounds and pre.valid_storage_all() holds,
            // pre.valid_storage_at_idx(i) holds. And since post.valid_storage_at_idx(i)
            // has the same structure as pre.valid_storage_at_idx(i) for i != tail,
            // and we've shown it directly for i == tail, the result follows.

            // More formally:
            // Case 1: i == tail
            if i == tail {
                // post.producer changes to Producing(tail)
                assert(post.producer == ProducerState::Producing(tail));
                assert(post.is_checked_out(i));
                // post.storage removes tail
                assert(post.storage.dom() == pre.storage.dom().remove(tail));
                assert(!post.storage.dom().contains(i));
            }
            // Case 2: i != tail
            else {
                // is_checked_out unchanged for i != tail
                assert(post.is_checked_out(i) == pre.is_checked_out(i));

                // Storage domain: remove(tail) doesn't affect i
                assert(post.storage.dom() == pre.storage.dom().remove(tail));
                assert(post.storage.dom().contains(i) == pre.storage.dom().contains(i));

                // Storage index: remove different key preserves value
                assert(post.storage.index(i) == pre.storage.index(i));

                // Now use pre.valid_storage_at_idx(i) to show post.valid_storage_at_idx(i)
                // since pre.valid_storage_all() holds
                assert(pre.valid_storage_at_idx(i));

                if pre.is_checked_out(i) {
                    assert(!pre.storage.dom().contains(i));
                    assert(!post.storage.dom().contains(i));
                    assert(post.is_checked_out(i));
                } else {
                    assert(pre.storage.dom().contains(i));
                    assert(post.storage.dom().contains(i));
                    assert(post.storage.index(i).id() == pre.storage.index(i).id());
                    assert(pre.storage.index(i).id() == pre.backing_cells.index(i as int));
                    assert(post.backing_cells.index(i as int) == pre.backing_cells.index(i as int));
                    assert(post.storage.index(i).is_init() == pre.storage.index(i).is_init());
                    assert(post.storage.index(i).is_uninit() == pre.storage.index(i).is_uninit());
                    assert(post.in_active_range(i) == pre.in_active_range(i));
                }
            }
        };
    };
}

