    // 
    // Proof outline:
    // Fix an arbitrary i such that 0 <= i < post.len().
    // We need to show post.valid_storage_at_idx(i).
    // 
    // Case 1: i == tail
    //   post.producer = Producing(tail), so post.is_checked_out(i) = true
    //   post.storage.dom() = pre.storage.dom().remove(tail), so i not in post.storage.dom()
    //   Therefore post.valid_storage_at_idx(i) holds.
    //
    // Case 2: i != tail  
    //   post.producer = Producing(tail), pre.producer = Idle(tail)
    //   So post.is_checked_out(i) = pre.is_checked_out(i) (since producer == Producing(i) only when i == tail)
    //   post.storage.dom() = pre.storage.dom().remove(tail)
    //   Since i != tail, i in post.storage.dom() iff i in pre.storage.dom()
    //   post.storage.index(i) = pre.storage.index(i) (axiom_map_remove_different)
    //   Since pre.valid_storage_all() holds, pre.valid_storage_at_idx(i) holds
    //   And post.valid_storage_at_idx(i) has the same structure as pre.valid_storage_at_idx(i)
    //   Therefore post.valid_storage_at_idx(i) holds.

    // More formally using the quantifier:
    assert(forall|i: nat| 0 <= i && i < post.len() ==> post.valid_storage_at_idx(i)) by {
        // For any i in bounds, show post.valid_storage_at_idx(i)
        assert forall|i: nat| 0 <= i && i < post.len() ==> post.valid_storage_at_idx(i) by {
            // Fix i, show post.valid_storage_at_idx(i)
            // We know: pre.valid_storage_all() holds, so pre.valid_storage_at_idx(i) holds
            // And we know the relationship between pre and post

            // First show some helpful equalities:
            assert(post.producer == ProducerState::Producing(tail));
            assert(post.storage.dom() == pre.storage.dom().remove(tail));

            if i == tail {
                // Case 1: i == tail
                assert(post.is_checked_out(i));
                assert(!post.storage.dom().contains(i));
            } else {
                // Case 2: i != tail
                assert(post.is_checked_out(i) == pre.is_checked_out(i));
                assert(post.storage.dom().contains(i) == pre.storage.dom().contains(i));
                assert(post.storage.index(i) == pre.storage.index(i));

                // Now show post.valid_storage_at_idx(i)
                // by using pre.valid_storage_at_idx(i)
                // and the equalities above
                if pre.is_checked_out(i) {
                    assert(!pre.storage.dom().contains(i));
                    assert(!post.storage.dom().contains(i));
                    assert(post.is_checked_out(i));
